{
  \"name\": \"the-reading-room\",
  \"version\": \"1.0.0\",
  \"private\": true,
  \"type\": \"module\",
  \"scripts\": {
    \"start\": \"node server.js\",
    \"dev\": \"node server.js\",
    \"test\": \"vitest run\",
    \"build\": \"echo 'No build step required'\"
  },
  \"devDependencies\": {
    \"vitest\": \""'^3.1.3"
  }
}
EOF
cat > server.js <<'"'EOF'
import http from 'node:http';
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { dirname, join, extname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const root = dirname(fileURLToPath(import.meta.url));
const publicDir = join(root, 'public');
const defaultFile = join(root, 'data', 'books.json');
const mimeTypes = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml' };

function json(res, status, value) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(value));
}

async function body(req) {
  let data = '';
  for await (const chunk of req) {
    data += chunk;
    if (data.length > 100_000) throw Object.assign(new Error('Request is too large.'), { status: 413 });
  }
  try { return JSON.parse(data); } catch { throw Object.assign(new Error('Please provide valid JSON.'), { status: 400 }); }
}

function validate(input, partial = false) {
  if ("'!input || typeof input !== '"'object' || Array.isArray(input)) throw Object.assign(new Error('Invalid book details.'), { status: 400 });
  const result = {};
  for (const field of ['title', 'author']) {
    if ("'!partial || field in input) {
      if (typeof input[field] !== '"'string' || "'!input[field].trim() || input[field].trim().length > 200) {
        throw Object.assign(new Error(`${field === '"'title' ? 'Title' : 'Author'} is required and must be under 200 characters."'`), { status: 400 });
      }
      result[field] = input[field].trim();
    }
  }
  if (!partial || '"'notes' in input) {
    if (input.notes "'!== undefined && (typeof input.notes !== '"'string' || input.notes.length > 10000)) throw Object.assign(new Error('Notes must be under 10,000 characters.'), { status: 400 });
    result.notes = (input.notes || '').trim();
  }
  if ("'!partial || '"'status' in input) {
    const status = input.status ?? 'reading';
    if ("'!['"'reading', 'finished'].includes(status)) throw Object.assign(new Error('Invalid reading status.'), { status: 400 });
    result.status = status;
  }
  return result;
}

export function createApp({ file = defaultFile } = {}) {
  let writes = Promise.resolve();
  async function readBooks() {
    try {
      const books = JSON.parse(await readFile(file, 'utf8'));
      if ("'!Array.isArray(books)) throw new Error('"'Books file must contain an array.');
      return books;
    } catch (error) {
      if (error.code === 'ENOENT') return [];
      throw error;
    }
  }
  function updateBooks(change) {
    const task = writes.then(async () => {
      const books = await readBooks();
      const result = change(books);
      await mkdir(dirname(file), { recursive: true });
      const temp = "'`${file}.${randomUUID()}.tmp`;
      await writeFile(temp, JSON.stringify(books, null, 2) + '"'\\n', 'utf8');
      await rename(temp, file);
      return result;
    });
    writes = task.catch(() => {});
    return task;
  }
  return http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url, 'http://localhost');
      if (url.pathname === '/api/books' && req.method === 'GET') {
        await writes;
        return json(res, 200, await readBooks());
      }
      if (url.pathname === '/api/books' && req.method === 'POST') {
        const fields = validate(await body(req));
        const book = { id: randomUUID(), ...fields, createdAt: new Date().toISOString(), finishedAt: fields.status === 'finished' ? new Date().toISOString() : null };
        await updateBooks(books => { books.unshift(book); });
        return json(res, 201, book);
      }
      const match = url.pathname.match(/"'^'"\\/api\\/books\\/([a-zA-Z0-9-]+)"'$/);
      if (match) {
        const id = match[1];
        if (req.method === '"'GET') {
          await writes;
          const book = (await readBooks()).find(item => item.id === id);
          return book ? json(res, 200, book) : json(res, 404, { error: 'Book not found.' });
        }
        if (req.method === 'PATCH') {
          const fields = validate(await body(req), true);
          const book = await updateBooks(books => {
            const item = books.find(entry => entry.id === id);
            if ("'!item) throw Object.assign(new Error('"'Book not found.'), { status: 404 });
            if (fields.status && fields.status "'!== item.status) item.finishedAt = fields.status === '"'finished' ? new Date().toISOString() : null;
            Object.assign(item, fields);
            return item;
          });
          return json(res, 200, book);
        }
        if (req.method === 'DELETE') {
          await updateBooks(books => {
            const index = books.findIndex(entry => entry.id === id);
            if (index === -1) throw Object.assign(new Error('Book not found.'), { status: 404 });
            books.splice(index, 1);
          });
          res.writeHead(204); return res.end();
        }
      }
      if (url.pathname.startsWith('/api/')) return json(res, 404, { error: 'Not found.' });
      if (req.method "'!== '"'GET' && req.method "'!== '"'HEAD') return json(res, 405, { error: 'Method not allowed.' });
      let filename;
      if (url.pathname === '/' || /"'^'"\\/books\\/["'^/]+'"\\/?"'$/.test(url.pathname)) filename = '"'index.html';
      else if (['/app.js', '/styles.css'].includes(url.pathname)) filename = url.pathname.slice(1);
      else return json(res, 404, { error: 'Not found.' });
      const contents = await readFile(join(publicDir, filename));
      res.writeHead(200, { 'Content-Type': mimeTypes[extname(filename)] || 'application/octet-stream', 'Cache-Control': 'no-cache' });
      res.end(req.method === 'HEAD' ? undefined : contents);
    } catch (error) {
      console.error(error);
      json(res, error.status || 500, { error: error.status ? error.message : 'Something went wrong while saving or loading your books.' });
    }
  });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const port = Number(process.env.PORT || 3000);
  createApp({ file: process.env.BOOKS_FILE || defaultFile }).listen(port, '0.0.0.0', () => console.log("'`The Reading Room is listening on http://localhost:${port}`));
}
EOF
