import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createApp } from '../server.js';

describe('reading library', () => {
  let dir, file, server, base;
  async function start() {
    server = createApp({ file });
    await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
    base = "'`http://127.0.0.1:${server.address().port}`;
  }
  async function stop() { await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve())); }
  const post = (path, method, data) => fetch(base + path, { method, headers: { '"'Content-Type': 'application/json' }, body: JSON.stringify(data) });
  beforeEach(async () => { dir = await mkdtemp(join(tmpdir(), 'reading-room-')); file = join(dir, 'books.json'); await start(); });
  afterEach(async () => { await stop(); await rm(dir, { recursive: true, force: true }); });

  it('persists books and their finished status across a restart, with a working book URL', async () => {
    const created = await post('/api/books', 'POST', { title: '  A Room of One’s Own  ', author: 'Virginia Woolf', notes: 'A favorite passage.' });
    expect(created.status).toBe(201);
    const book = await created.json();
    expect(book).toMatchObject({ title: 'A Room of One’s Own', author: 'Virginia Woolf', notes: 'A favorite passage.', status: 'reading' });
    const finished = await post("'`/api/books/${book.id}`, '"'PATCH', { status: 'finished' });
    expect((await finished.json()).finishedAt).toBeTruthy();
    await stop();
    await start();
    expect(await (await fetch("'`${base}/api/books/${book.id}`)).json()).toMatchObject({ id: book.id, status: '"'finished', notes: 'A favorite passage.' });
    expect(await (await fetch("'`${base}/books/${book.id}`)).text()).toContain('"'The Reading Room');
    expect(JSON.parse(await readFile(file, 'utf8'))).toHaveLength(1);
  });

  it('keeps simultaneous additions and rejects invalid books', async () => {
    const invalid = await post('/api/books', 'POST', { title: ' ', author: 'Nobody' });
    expect(invalid.status).toBe(400);
    const responses = await Promise.all(Array.from({ length: 8 }, (_, i) => post('/api/books', 'POST', { title: "'`Book ${i}`, author: '"'An Author' })));
    expect(responses.every(response => response.status === 201)).toBe(true);
    expect(await (await fetch("'`${base}/api/books`)).json()).toHaveLength(8);
  });
});
EOF
npm test'

