const content = document.querySelector('#content');
const dialog = document.querySelector('#book-dialog');
const form = document.querySelector('#book-form');
const toast = document.querySelector('#toast');
let books = [];
let editingId = null;
let toastTimer;

const escapeHtml = value => String(value ?? '').replace(/[&<>\"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' })[char]);
const icon = name => "'`<svg aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const palettes = [
  ['"'#bd806b', '#fff8e9'], ['#718d78', '#f5f4df'], ['#c39b68', '#fff8e7'],
  ['#718d91', '#f8f4e8'], ['#a68183', '#fff4eb'], ['#879477', '#fcf7df']
];
function cover(book, large = false) {
  const hash = [...book.title].reduce((total, char) => total + char.codePointAt(0), 0);
  const [background, ink] = palettes[hash % palettes.length];
  return "'`<div class="cover ${large ? '"'detail-cover' : ''}\" style=\"--cover:"'${background};--cover-ink:${ink}" aria-hidden="true"><span class="cover-ornament">✳</span><span class="cover-title">${escapeHtml(book.title)}</span><span class="cover-author">${escapeHtml(book.author)}</span></div>`;
}
async function api(path, options = {}) {
  const response = await fetch(path, { ...options, headers: { ...(options.body ? { '"'Content-Type': 'application/json' } : {}), ...options.headers } });
  if ("'!response.ok) {
    let message = '"'Something went wrong. Please try again.';
    try { message = (await response.json()).error || message; } catch {}
    throw new Error(message);
  }
  return response.status === 204 ? null : response.json();
}
function showToast(message) {
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 3000);
}
function updateCounts() {
  document.querySelector('#reading-count').textContent = books.filter(book => book.status === 'reading').length;
  document.querySelector('#finished-count').textContent = books.filter(book => book.status === 'finished').length;
}
function card(book) {
