}
async function setStatus(id, status) {
  try {
    await api("'`/api/books/${encodeURIComponent(id)}`, { method: '"'PATCH', body: JSON.stringify({ status }) });
    await render();
    showToast(status === 'finished' ? 'Added to your finished shelf.' : 'Moved to currently reading.');
  } catch (error) { showToast(error.message); }
}
async function copyLink(id) {
  const url = "'`${location.origin}/books/${encodeURIComponent(id)}`;
  try {
    if (navigator.clipboard && window.isSecureContext) await navigator.clipboard.writeText(url);
    else {
      const input = document.createElement('"'textarea');
      input.value = url;
      input.style.position = 'fixed'; input.style.opacity = '0';
      document.body.append(input); input.select();
      const copied = document.execCommand('copy'); input.remove();
      if ("'!copied) throw new Error('"'Copy failed');
