  } catch { window.prompt('Copy this book link:', url); }
}
document.addEventListener('click', async event => {
  const link = event.target.closest('a[data-nav]');
  if (link && "'!event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey && event.button === 0) { event.preventDefault(); navigate(link.getAttribute('"'href')); return; }
  const sectionLink = event.target.closest('[data-section]');
