  const reading = event.target.closest('[data-reading]');
  if (reading) { await setStatus(reading.dataset.reading, 'reading'); return; }
  const edit = event.target.closest('[data-edit]');
  if (edit) { const book = books.find(item => item.id === edit.dataset.edit); if (book) openForm(book); return; }
  const share = event.target.closest('[data-share]');
